"use client";
import React from "react";
// ── Input monetário com máscara R$ ──
function MoneyInput({value,onChange,placeholder,style:sx}){
  // Formata número → "1.890.000,00"
  const fmt=v=>{
    if(v===null||v===undefined||v==="") return "";
    const n=Number(v);
    if(isNaN(n)) return "";
    return n.toLocaleString("pt-BR",{minimumFractionDigits:2,maximumFractionDigits:2});
  };

  // Converte string digitada → número
  // Aceita: "850000" | "850.000" | "850.000,00" | "850,000.00"
  const parse=raw=>{
    if(!raw) return null;
    let s=raw.replace(/[R$\s]/g,"").trim();
    if(!s) return null;
    const hasDot=s.includes(".");
    const hasComma=s.includes(",");
    if(hasDot&&hasComma){
      // Com ponto e vírgula: verificar qual vem por último (é o decimal)
      const lastComma=s.lastIndexOf(",");
      const lastDot=s.lastIndexOf(".");
      if(lastComma>lastDot){
        // BR: 1.890.000,00 → remove pontos, vírgula vira ponto
        s=s.replace(/\./g,"").replace(",",".");
      } else {
        // US: 1,890,000.00 → remove vírgulas
        s=s.replace(/,/g,"");
      }
    } else if(hasDot&&!hasComma){
      // Só ponto: verificar se é separador de milhar ou decimal
      const parts=s.split(".");
      const lastPart=parts[parts.length-1];
      if(parts.length>2||(parts.length===2&&lastPart.length===3)){
        // Milhar BR: "850.000" ou "1.850.000" — remove pontos
        s=s.replace(/\./g,"");
      }
      // Senão mantém como decimal: "850.50"
    } else if(hasComma&&!hasDot){
      // Só vírgula
      const parts=s.split(",");
      if(parts.length===2&&parts[1].length<=2){
        // Decimal BR: "850,00" → "850.00"
        s=s.replace(",",".");
      } else {
        // Milhar US: "1,000,000" → remove vírgulas
        s=s.replace(/,/g,"");
      }
    }
    const n=parseFloat(s);
    return isNaN(n)?null:n;
  };

  const [display,setDisplay]=React.useState(fmt(value));
  const [focused,setFocused]=React.useState(false);

  React.useEffect(()=>{
    if(!focused) setDisplay(fmt(value));
  },[value,focused]);

  return React.createElement("input",{
    style:{...s.inp,...(sx||{})},
    value:focused?display:(value!==null&&value!==undefined&&value!==""?"R$ "+fmt(value):""),
    placeholder:placeholder||"R$ 0,00",
    onFocus:e=>{
      setFocused(true);
      // Ao focar, mostra o número sem formatação para facilitar edição
      const n=Number(value);
      setDisplay(!isNaN(n)&&value!==""?String(n):"");
      // Seleciona tudo
      setTimeout(()=>e.target.select(),0);
    },
    onBlur:()=>{
      setFocused(false);
      const n=parse(display);
      if(n!==null&&n>=0) onChange(n);
      else if(!display||display.trim()==="") onChange("");
    },
    onChange:e=>setDisplay(e.target.value),
    inputMode:"numeric",
  });
}
