// CEP FIELD — busca automática via ViaCEP
// Props:
//   cepKey       — chave do cep no state (ex: "prop_cep" ou "cep_imovel")
//   fieldMap     — { rua, bairro, cidade, uf } → chaves no state a preencher
//   f, u         — state e updater do formulário pai
function CepField({ cepKey, fieldMap, f, u }) {
  const [cepStatus, setCepStatus] = useState("idle"); // idle | loading | ok | error

  function maskCep(v) {
    const d = v.replace(/\D/g, "").slice(0, 8);
    return d.length > 5 ? d.slice(0, 5) + "-" + d.slice(5) : d;
  }

  function aplicarEndereco(rua,bairro,cidade,uf){
    if (fieldMap.rua    && rua)    u(fieldMap.rua,    rua);
    if (fieldMap.bairro && bairro) u(fieldMap.bairro, bairro);
    if (fieldMap.cidade && cidade) u(fieldMap.cidade, cidade);
    if (fieldMap.uf     && uf)     u(fieldMap.uf,     uf);
  }

  async function buscarCep(raw) {
    const digits = raw.replace(/\D/g, "");
    if (digits.length !== 8) { setCepStatus("idle"); return; }
    setCepStatus("loading");
    // Tenta ViaCEP primeiro
    try {
      const res = await fetch(`https://viacep.com.br/ws/${digits}/json/`);
      const data = await res.json();
      if (!data.erro && (data.logradouro || data.bairro || data.localidade)) {
        aplicarEndereco(data.logradouro, data.bairro, data.localidade, data.uf);
        setCepStatus("ok");
        return;
      }
    } catch { /* segue para fallback */ }
    // Fallback: BrasilAPI
    try {
      const res2 = await fetch(`https://brasilapi.com.br/api/cep/v1/${digits}`);
      if (res2.ok) {
        const data2 = await res2.json();
        aplicarEndereco(data2.street, data2.neighborhood, data2.city, data2.state);
        setCepStatus("ok");
        return;
      }
    } catch { /* segue para erro */ }
    setCepStatus("error");
  }

  const statusIcon =
    cepStatus === "loading" ? <span style={s.t12s}>Buscando endereço...</span> :
    cepStatus === "ok"      ? <span style={{fontSize:12,color:C.ok}}>✓ Endereço preenchido automaticamente</span> :
    cepStatus === "error"   ? <span style={{fontSize:12,color:"#dc2626"}}>CEP não encontrado — preencha manualmente ou tente novamente</span> :
    <span style={{fontSize:11,color:C.soft}}>Digite os 8 dígitos para auto-completar rua, bairro e cidade</span>;

  return (
    <div style={s.fld}>
      <label style={s.lbl}>CEP</label>
      <div style={{position:"relative",display:"flex",gap:6}}>
        <input
          style={{
            ...s.inp,
            borderColor: cepStatus==="ok" ? C.ok : cepStatus==="error" ? "#dc2626" : undefined,
            paddingRight: 36,
          }}
          value={f[cepKey] || ""}
          placeholder="00000-000"
          maxLength={9}
          onChange={e => {
            const masked = maskCep(e.target.value);
            u(cepKey, masked);
            buscarCep(masked);
          }}
          onBlur={e => buscarCep(e.target.value)}
        />
        {cepStatus === "loading" && (
          <span style={{
            position:"absolute", right:10, top:"50%", transform:"translateY(-50%)",
            width:14, height:14, border:`2px solid ${C.line}`, borderTopColor:C.b1,
            borderRadius:"50%", display:"inline-block",
            animation:"spin 1s linear infinite",
          }}/>
        )}
        {cepStatus === "ok" && (
          <span style={{position:"absolute",right:10,top:"50%",transform:"translateY(-50%)",color:C.ok,fontSize:16}}>✓</span>
        )}
        {cepStatus === "error" && (
          <button type="button" onClick={()=>buscarCep(f[cepKey]||"")} title="Tentar buscar novamente" style={{position:"absolute",right:4,top:"50%",transform:"translateY(-50%)",background:"none",border:"none",cursor:"pointer",color:"#dc2626",fontSize:11,fontWeight:700,fontFamily:"inherit"}}>↻</button>
        )}
      </div>
      <span style={s.note}>{statusIcon}</span>
    </div>
  );
}

