      rows.push(fieldBool("Lavabo",f.lavabo));
      rows.push(field("Config. de vagas",f.config_vagas));
      rows.push(fieldBool("Escaninho/Depósito",f.escaninho));
      rows.push(field("Posição solar",f.posicao));
      rows.push(field("Vista",f.vista));
      rows.push(field("Estado / Reforma",f.reforma));
      rows.push(field("Mobília",f.mobilia));
      rows.push(field("Taxa de condomínio",fmtR(f.condo)?(fmtR(f.condo)+"/mês"):null));
      rows.push(field("Situação de ocupação",f.situacao_ocup));
      rows.push(field("Valor pedido",fmtR(f.preco_pedido)));
      rows.push(field("IPTU",fmtR(f.iptu)));
      rows.push(fieldBool("Matrícula disponível",f.matricula));
      rows.push(field("Situação",f.quitado?"Quitado":f.financiamento?"Com financiamento":null));
