function validarConsistencia(f,comparaveis){
  const alerts=[];
  const suites=Number(f.suites)||0, area=Number(f.area)||0, quartos=Number(f.quartos)||0;
  if(area&&suites&&(area/suites)<12){
    alerts.push({level:"bloqueio",texto:`${suites} suíte${suites!==1?"s":""} em ${area}m² parece atípico. Confirme essa informação antes de concluir a análise.`});
  }
  if(suites&&quartos&&suites>quartos){
    alerts.push({level:"atencao",texto:`Número de suítes (${suites}) maior que o de dormitórios (${quartos}). Confirme se está correto.`});
  }
  if(!f.vagas) alerts.push({level:"atencao",texto:"Ausência de vagas informadas."});
  if(!f.bairro) alerts.push({level:"atencao",texto:"Ausência de bairro."});
  if(!f.area&&!f.area_total_rural) alerts.push({level:"atencao",texto:"Ausência de área."});
  if(!f.diferenciais&&!f.loc_dif&&!f.voc_dif) alerts.push({level:"atencao",texto:"Imóvel sem diferenciais preenchidos."});
  if((comparaveis||[]).length>0&&(comparaveis||[]).length<3) alerts.push({level:"atencao",texto:"Comparáveis insuficientes — recomenda-se ao menos 3 para uma leitura consistente."});
  return alerts;
}

function diagnosticoPreco(f,precoRecomendado){
  if(!f.preco_pedido||!precoRecomendado) return {label:"Sem dados suficientes",cor:"#6b7280",bg:"#f4f5f7",explicacao:null,alerta:null};
  const diff=(Number(f.preco_pedido)-Number(precoRecomendado))/Number(precoRecomendado);
  const explicacao="Este diagnóstico compara o preço informado pelo proprietário com o preço justo de mercado — considerando transações reais, comparáveis e desconto médio de negociação.";
  if(diff>0.25) return {label:"Muito acima do mercado",cor:"#991b1b",bg:"#fee2e2",explicacao,alerta:"O preço informado está significativamente acima da Faixa de Venda Rápida. Imóveis nessa faixa tendem a receber poucos contatos, poucas visitas e poucas propostas."};
  if(diff>0.12) return {label:"Acima da faixa de liquidez",cor:"#92400e",bg:"#fef3c7",explicacao,alerta:"O preço informado está acima da Faixa de Venda Rápida. Ajustar o preço pode aumentar a geração de visitas e propostas."};
  if(diff>0.05) return {label:"Levemente acima",cor:"#1e43f9",bg:"#eff4ff",explicacao,alerta:"O preço está levemente acima da faixa recomendada — a diferença pode ser absorvida em negociação."};
  if(diff>=-0.05) return {label:"Bem posicionado",cor:"#065f46",bg:"#dcfce7",explicacao,alerta:null};
  if(diff>=-0.15) return {label:"Competitivo",cor:"#065f46",bg:"#dcfce7",explicacao,alerta:null};
  return {label:"Abaixo do potencial",cor:"#0022bd",bg:"#eff4ff",explicacao,alerta:"O valor pedido está abaixo da faixa observada — há espaço para defender um posicionamento mais atrativo ao proprietário."};
}

