function classificarIdadeAnuncio(dataRef){
  if(!dataRef) return {dias:null,status:"Sem data"};
  const dias=Math.round((Date.now()-new Date(dataRef).getTime())/86400000);
  if(dias<0) return {dias:0,status:"Atual"};
  if(dias<=30) return {dias,status:"Atual"};
  if(dias<=120) return {dias,status:"Recente"};
  return {dias,status:"Desatualizado"};
}

function gerarArgumentoTexto(f,results,estrategiaLabel){
  const nome=(f.prop_nome||"").split(" ")[0]||"Olá";
  const rec=results?.sugestao_preco_recomendado;
  return `${nome}, o objetivo desta análise é posicionar seu imóvel com inteligência, para que ele entre no mercado com força real de venda.\n\nPelos comparáveis avaliados, percebemos que existe uma faixa de preço mais sensível para gerar visitas e propostas. Quando o imóvel entra muito acima dessa faixa, ele pode até preservar o valor desejado no papel, mas tende a perder tração comercial.${rec?` O preço recomendado pela análise é de R$ ${Number(rec).toLocaleString("pt-BR",{minimumFractionDigits:2,maximumFractionDigits:2})}.`:""}\n\nMinha recomendação é trabalhar com um preço que preserve valor, mas que também torne o imóvel competitivo. Assim aumentamos a chance de atrair compradores reais, gerar visitas qualificadas e construir uma negociação mais forte.${estrategiaLabel?`\n\nEstratégia sugerida: ${estrategiaLabel}.`:""}`;
}

// PÁGINA PÚBLICA — Análise Estratégica de Precificação

function tipoLabelItem(item){
  return item.subcatCasa==="rua"?"Casa de Rua":item.subcatCasa==="condo"?"Casa em Condomínio":item.cat==="apartamento"?"Apartamento":item.cat==="terreno"?(item.subcatCasa==="condo"?"Terreno em Condomínio":"Terreno Urbano"):item.cat==="comercial"?(item.f?.tipo_com||"Comercial"):(item.f?.tipo_rural||"Rural");
}
function computeBadgesBk(item){
  const badges=[];
  const f=item.f||{};
  if(!f._precDone) badges.push({label:"Precificação pendente",bg:"#fef9c3",cor:"#78350f"});
  else badges.push({label:"Precificação concluída",bg:"#dcfce7",cor:"#065f46"});
  if(item.validStatus==="ajuste") badges.push({label:"Ajuste solicitado",bg:"#fef9c3",cor:"#78350f"});
  if(item.validStatus==="reprovado") badges.push({label:"Recusada",bg:"#fee2e2",cor:"#991b1b"});
  if(!f.bairro||!(f.area||f.area_total_rural)||!f.prop_nome) badges.push({label:"Dados incompletos",bg:"#fee2e2",cor:"#991b1b"});
  if(item.validStatus==="aprovado"&&(item.latStatus==="pendente_integracao"||item.latStatus==="concluido")) badges.push({label:"Enviado ao Latitude",bg:"#dcfce7",cor:"#065f46"});
  else if(item.validStatus==="aprovado") badges.push({label:"Pronto para Latitude",bg:"#eff4ff",cor:C.b1});
  return badges;
}
function computeProximaAcaoBk(item){
  const f=item.f||{};
  if(!f.bairro||!(f.area||f.area_total_rural)||!f.prop_nome) return "Solicitar ajuste";
  if(!f._precDone) return "Revisar precificação";
  
  if(item.validStatus==="ajuste") return "Ver solicitação do proprietário";
  if(!item.validStatus) return "Aprovar captação";
  if(item.validStatus==="aprovado"&&item.latStatus!=="pendente_integracao"&&item.latStatus!=="concluido") return "Preparar para Latitude";
  if(item.validStatus==="aprovado") return "Subir para o Latitude";
  return "Acompanhar";
}
function statusBkOf(item){
  const f=item.f||{};
  if(item.validStatus==="reprovado") return "recusado";
  if(item.validStatus==="aprovado"&&(item.latStatus==="pendente_integracao"||item.latStatus==="concluido")) return "enviada_latitude";
  if(item.validStatus==="aprovado") return "pronta_latitude";
  if(item.validStatus==="ajuste") return "ajuste";
  return "fila";
  if(!f._precDone) return "prec_pendente";
}

