const DOC_STATUS_OPCOES=["Não solicitado","Solicitado","Recebido","Dispensado"];

function dadosBasicosOk(f){ return !!(f.bairro&&(f.area||f.area_total_rural)); }

function computeSecStatus(item){
  const f=item.f||{};
  if(item.secEncaminhado) return "encaminhada";
  if(item.validStatus==="ajuste") return "ajuste";
  
  if(!f.prop_fone||!dadosBasicosOk(f)) return "dados_incompletos";
  return "nova";
  return "pronta_bk";
}
