  nova:{label:"Nova captação",bg:"#eef2ff",cor:C.b1},
  dados_incompletos:{label:"Dados incompletos",bg:"#fef2f2",cor:"#991b1b"},
  aguardando_prop:{label:"Aguardando proprietário",bg:"#fefce8",cor:"#78350f"},
  ajuste:{label:"Ajuste solicitado",bg:"#fefce8",cor:"#78350f"},
