// APP PRINCIPAL
// MODAL PDF — renderiza HTML em iframe dentro do artefato
function PdfModal({ html, onClose, filename }){
  const ref = useRef(null);

  function baixar(){
    try {
      const blob = new Blob([html], { type: "text/html;charset=utf-8" });
      const url = URL.createObjectURL(blob);
      const a = document.createElement("a");
      a.href = url;
      a.download = filename||"mybroker-captacao.html";
      document.body.appendChild(a);
      a.click();
      document.body.removeChild(a);
      URL.revokeObjectURL(url);
    } catch(e){ console.error(e); }
  }

  function imprimir(){
    try {
      const iframe = ref.current;
      if(iframe && iframe.contentWindow) iframe.contentWindow.print();
    } catch(e){
      // Fallback: abrir em nova aba via blob
      try {
        const blob = new Blob([html], { type: "text/html;charset=utf-8" });
        const url = URL.createObjectURL(blob);
        const w = window.open(url, "_blank");
        if(w) setTimeout(()=>w.print(), 800);
      } catch(e2){ baixar(); }
    }
  }

  return(
    <div style={{position:"fixed",inset:0,zIndex:100,background:"rgba(0,0,0,.6)",display:"flex",alignItems:"center",justifyContent:"center",padding:16}}>
      <div style={{width:"100%",maxWidth:900,height:"90vh",background:"#fff",borderRadius:8,overflow:"hidden",display:"flex",flexDirection:"column",boxShadow:"0 20px 60px rgba(0,0,0,.3)"}}>
        <div style={{display:"flex",justifyContent:"space-between",alignItems:"center",padding:"12px 20px",borderBottom:"1px solid #eee",flexShrink:0}}>
          <span style={{fontSize:13,fontWeight:700,color:"#111"}}>Documento MyBroker</span>
          <div style={s.f8}>
            <button onClick={imprimir} style={{padding:"6px 16px",background:"#092f68",color:"#fff",border:"none",borderRadius:4,fontSize:11,fontWeight:700,cursor:"pointer",fontFamily:"inherit"}}>🖨 Imprimir</button>
            <button onClick={baixar} style={{padding:"6px 16px",background:"#17a34a",color:"#fff",border:"none",borderRadius:4,fontSize:11,fontWeight:700,cursor:"pointer",fontFamily:"inherit"}}>⬇ Baixar arquivo</button>
            <button onClick={onClose} style={{padding:"6px 16px",background:"#f4f5f7",color:"#666",border:"1px solid #ddd",borderRadius:4,fontSize:11,fontWeight:600,cursor:"pointer",fontFamily:"inherit"}}>✕ Fechar</button>
          </div>
        </div>
        <iframe ref={ref} srcDoc={html} style={{flex:1,border:"none",width:"100%"}} title="PDF"/>
      </div>
    </div>
  );
}

// SISTEMA DE AUTENTICAÇÃO E CONTROLE DE ACESSO

const PERFIS={
  corretor:{label:"Corretor",cor:"#1e43f9",bg:"#eef2ff",icon:"briefcase",desc:"Capta e acompanha suas captações"},
  gerente:{label:"Gerente",cor:"#78350f",bg:"#fefce8",icon:"userCheck",desc:"Acompanha a equipe e valida comercialmente"},
  backoffice:{label:"Backoffice",cor:"#065f46",bg:"#ecfdf5",icon:"shieldCheck",desc:"Valida qualidade e prepara para publicação"},
  diretoria:{label:"Diretoria/Admin",cor:"#092f68",bg:"#eef2ff",icon:"chartBar",desc:"Acesso total e configuração da plataforma"},
};

const STATUS_USUARIO={
  aguardando_aprovacao:{label:"Aguardando aprovação",cor:"#9a3412",bg:"#ffedd5"},
  convite_pendente:{label:"Convite pendente",cor:"#78350f",bg:"#fefce8"},
  ativo:{label:"Ativo",cor:"#065f46",bg:"#ecfdf5"},
  inativo:{label:"Inativo",cor:"#6b7280",bg:"#f4f6fb"},
  bloqueado:{label:"Bloqueado",cor:"#991b1b",bg:"#fef2f2"},
};

function gerarToken(){
  const arr=new Uint8Array(24);
  crypto.getRandomValues(arr);
  return Array.from(arr,b=>b.toString(16).padStart(2,"0")).join("");
}

async function getUsers(){
  const r=await fetch("/api/users",{credentials:"same-origin"});
  if(r.status===401){window.location.href="/login";return [];}
  const j=await r.json().catch(()=>({}));
  if(!r.ok) throw new Error(j.error||"Erro ao carregar usuários");
  return j.users||[];
}
async function saveUsers(users){
  const r=await fetch("/api/users",{method:"PUT",headers:{"Content-Type":"application/json"},credentials:"same-origin",body:JSON.stringify({users})});
  const j=await r.json().catch(()=>({}));
  if(!r.ok){const m=j.error||"Erro ao salvar usuários";alert(m);throw new Error(m);}
  return j.users||users;
}
async function clearSession(){try{await fetch("/api/logout",{method:"POST",credentials:"same-origin"});}catch(e){}}

function GestaoUsuarios({usuarioAtual,onClose}){
  const [users,setUsers]=useState([]);
  const [loading,setLoading]=useState(true);
  const [erro,setErro]=useState("");
  const [linkCopiado,setLinkCopiado]=useState("");
  const [editandoPerfil,setEditandoPerfil]=useState(null);
  const [form,setForm]=useState({nome:"",email:"",whatsapp:"",perfil:"corretor",creci:"",gerente:""});

  useEffect(()=>{getUsers().then(u=>{setUsers(u);setLoading(false);});}, []);

  async function convidar(){
    setErro("");
    if(!form.nome||!form.email){setErro("Nome e e-mail são obrigatórios.");return;}
    if(users.find(u=>u.email.toLowerCase()===form.email.toLowerCase())){setErro("E-mail já cadastrado.");return;}
    const token=gerarToken();
    const novo={id:"u_"+Date.now().toString(36),nome:form.nome,email:form.email,whatsapp:form.whatsapp,perfil:form.perfil,creci:form.creci,gerente:form.gerente,status:"convite_pendente",senha:null,tokenConvite:token,tokenConviteAt:new Date().toISOString(),criadoPor:usuarioAtual.id,criadoEm:new Date().toISOString()};
    const updated=[...users,novo];
    await saveUsers(updated);setUsers(updated);
    setForm({nome:"",email:"",whatsapp:"",perfil:"corretor",creci:"",gerente:""});
    copiarLink(novo);
  }

  function gerarLinkConvite(user){return `${window.location.origin}/convite/${user.tokenConvite}`;}

  async function reenviarConvite(user){
    const t=gerarToken();
    const updated=users.map(u=>u.id===user.id?{...u,tokenConvite:t,tokenConviteAt:new Date().toISOString()}:u);
    await saveUsers(updated);setUsers(updated);
    copiarTexto(`${window.location.origin}/convite/${t}`,user.id+"_convite");
  }

  function copiarLink(user){copiarTexto(gerarLinkConvite(user),user.id+"_convite");}

  function copiarTexto(txt,key){
    try{navigator.clipboard.writeText(txt);}catch(e){}
    setLinkCopiado(key);setTimeout(()=>setLinkCopiado(""),2500);
  }

  function abrirWhatsApp(user){
    const link=gerarLinkConvite(user);
    const msg=`Olá, ${user.nome.split(" ")[0]}! 👋\n\nSeu acesso ao BrokerFlow Revenda da MyBroker foi criado.\n\nClique no link abaixo para criar sua senha:\n${link}\n\nPerfil: ${PERFIS[user.perfil]?.label||user.perfil}\n\nEquipe MyBroker`;
    const fone=(user.whatsapp||"").replace(/\D/g,"");
    window.open(fone?`https://wa.me/55${fone}?text=${encodeURIComponent(msg)}`:`https://wa.me/?text=${encodeURIComponent(msg)}`,"_blank");
  }

  async function alterarStatus(id,novoStatus){
    const updated=users.map(u=>u.id===id?{...u,status:novoStatus}:u);
    await saveUsers(updated);setUsers(updated);
  }

  async function alterarPerfil(id,novoPerfil){
    const updated=users.map(u=>u.id===id?{...u,perfil:novoPerfil}:u);
    await saveUsers(updated);setUsers(updated);setEditandoPerfil(null);
  }

  const gerentes=users.filter(u=>u.perfil==="gerente"||u.perfil==="diretoria");
  const inp={padding:"9px 12px",border:"1.5px solid #e2e8f0",borderRadius:8,fontSize:12,fontFamily:"inherit",background:"#fff",width:"100%",boxSizing:"border-box"};
  const statusCount=Object.fromEntries(Object.keys(STATUS_USUARIO).map(k=>[k,users.filter(u=>u.status===k).length]));

  if(loading) return(
    <div style={{position:"fixed",inset:0,background:"rgba(0,0,0,.6)",zIndex:200,display:"flex",alignItems:"center",justifyContent:"center"}}>
      <div style={{background:"#fff",padding:32,borderRadius:12,textAlign:"center",color:"#999"}}>Carregando...</div>
    </div>
  );

  return(
    <div style={{position:"fixed",inset:0,background:"rgba(0,0,0,.6)",zIndex:200,display:"flex",alignItems:"center",justifyContent:"center",padding:16}}>
      <div style={{background:"#fff",borderRadius:14,width:"100%",maxWidth:860,maxHeight:"92vh",overflow:"auto",boxShadow:"0 24px 64px rgba(0,0,0,.3)"}}>
        <div style={{background:"linear-gradient(135deg,#0f172a,#092f68)",padding:"24px 28px",borderRadius:"14px 14px 0 0",display:"flex",justifyContent:"space-between",alignItems:"center",position:"sticky",top:0,zIndex:10}}>
          <div>
            <div style={{fontSize:9.5,fontWeight:700,letterSpacing:2,textTransform:"uppercase",color:C.y,marginBottom:4}}>Diretoria / Admin</div>
            <div style={{fontSize:18,fontWeight:800,color:"#fff",letterSpacing:-.3}}>Gestão de Usuários</div>
            <div style={{fontSize:11,color:"rgba(255,255,255,.45)",marginTop:3}}>A Diretoria cria o acesso. O usuário cria a própria senha.</div>
          </div>
          <div style={{display:"flex",gap:8,alignItems:"center"}}>
            <div style={{display:"flex",gap:6,flexWrap:"wrap"}}>
              {Object.entries(STATUS_USUARIO).map(([k,v])=>statusCount[k]>0&&(
                <span key={k} style={{fontSize:9.5,fontWeight:700,padding:"3px 9px",borderRadius:20,background:"rgba(255,255,255,.1)",color:"#fff"}}>{v.label}: {statusCount[k]}</span>
              ))}
            </div>
            <button onClick={onClose} style={{background:"rgba(255,255,255,.1)",border:"none",color:"#fff",width:36,height:36,borderRadius:8,cursor:"pointer",fontSize:16}}>✕</button>
          </div>
        </div>

        <div style={{padding:24}}>
          <div style={{background:"#f8fafc",border:"1px solid #e2e8f0",borderRadius:12,padding:20,marginBottom:24}}>
            <div style={{fontSize:11,fontWeight:700,textTransform:"uppercase",letterSpacing:.5,color:"#64748b",marginBottom:14}}>Convidar novo usuário</div>
            <div style={{display:"grid",gridTemplateColumns:"repeat(auto-fit,minmax(150px,1fr))",gap:10,marginBottom:10}}>
              <div><label style={s.t95s}>Nome *</label><input style={inp} value={form.nome} onChange={e=>setForm({...form,nome:e.target.value})} placeholder="Nome completo"/></div>
              <div><label style={s.t95s}>E-mail *</label><input style={inp} type="email" value={form.email} onChange={e=>setForm({...form,email:e.target.value})} placeholder="email@mybroker.com.br"/></div>
              <div><label style={s.t95s}>WhatsApp</label><input style={inp} value={form.whatsapp} onChange={e=>setForm({...form,whatsapp:e.target.value})} placeholder="(34) 99999-9999"/></div>
              <div><label style={s.t95s}>Perfil *</label>
                <select style={inp} value={form.perfil} onChange={e=>setForm({...form,perfil:e.target.value})}>
                  {Object.entries(PERFIS).map(([k,v])=><option key={k} value={k}>{v.label}</option>)}
                </select>
              </div>
              <div><label style={s.t95s}>CRECI</label><input style={inp} value={form.creci} onChange={e=>setForm({...form,creci:e.target.value})} placeholder="Ex: 16520"/></div>
              {form.perfil==="corretor"&&<div><label style={s.t95s}>Gerente</label>
                <select style={inp} value={form.gerente} onChange={e=>setForm({...form,gerente:e.target.value})}>
                  <option value="">Sem gerente</option>
                  {gerentes.map(g=><option key={g.id} value={g.id}>{g.nome}</option>)}
                </select>
              </div>}
            </div>
            {erro&&<div style={{fontSize:12,color:"#991b1b",background:"#fef2f2",padding:"8px 12px",borderRadius:6,marginBottom:10}}>{erro}</div>}
            <div style={{display:"flex",alignItems:"center",gap:10}}>
              <button onClick={convidar} style={{padding:"9px 20px",background:C.b1,color:"#fff",border:"none",borderRadius:8,fontFamily:"inherit",fontWeight:700,fontSize:12,cursor:"pointer"}}>Gerar convite</button>
              <span style={{fontSize:11,color:"#94a3b8"}}>Link seguro gerado. A Diretoria nunca define a senha do usuário.</span>
            </div>
          </div>

          <div style={{fontSize:11,fontWeight:700,textTransform:"uppercase",letterSpacing:.5,color:"#64748b",marginBottom:12}}>Usuários ({users.length})</div>
          <div style={{display:"flex",flexDirection:"column",gap:8}}>
            {users.map(u=>{
              const p=PERFIS[u.perfil]||PERFIS.corretor;
              const st=STATUS_USUARIO[u.status]||STATUS_USUARIO.inativo;
              const copiadoConvite=linkCopiado===u.id+"_convite";
              const gerenteDele=users.find(g=>g.id===u.gerente);
              return(
                <div key={u.id} style={{background:"#fff",border:`1px solid ${u.status==="bloqueado"?"#fca5a5":u.status==="ativo"?"#e2e8f0":"#f1f5f9"}`,borderRadius:10,padding:"14px 16px",opacity:u.status==="inativo"?.6:1}}>
                  <div style={{display:"flex",alignItems:"flex-start",gap:12,flexWrap:"wrap"}}>
                    <div style={{width:36,height:36,borderRadius:10,background:p.bg,display:"flex",alignItems:"center",justifyContent:"center",flexShrink:0}}>
                      <Icon name={p.icon} size={16} color={p.cor}/>
                    </div>
                    <div style={{flex:1,minWidth:180}}>
                      <div style={{fontSize:13,fontWeight:700,color:"#0f172a",marginBottom:2}}>{u.nome}</div>
                      <div style={{fontSize:11,color:"#94a3b8"}}>{u.email}{u.whatsapp&&` · ${u.whatsapp}`}{u.creci&&` · CRECI ${u.creci}`}</div>
                      {gerenteDele&&<div style={{fontSize:10,color:"#94a3b8",marginTop:2}}>Gerente: {gerenteDele.nome}</div>}
                    </div>
                    <div style={{display:"flex",gap:6,alignItems:"center",flexWrap:"wrap"}}>
                      {editandoPerfil===u.id?(
                        <select defaultValue={u.perfil} onBlur={e=>alterarPerfil(u.id,e.target.value)} autoFocus style={{padding:"4px 8px",borderRadius:6,border:"1.5px solid #1e43f9",fontSize:11,fontFamily:"inherit",cursor:"pointer"}}>
                          {Object.entries(PERFIS).map(([k,v])=><option key={k} value={k}>{v.label}</option>)}
                        </select>
                      ):(
                        <button onClick={()=>u.id!==usuarioAtual.id&&setEditandoPerfil(u.id)} style={{fontSize:10,fontWeight:700,padding:"3px 10px",borderRadius:20,background:p.bg,color:p.cor,border:"none",cursor:u.id!==usuarioAtual.id?"pointer":"default"}}>{p.label}</button>
                      )}
                      <span style={{fontSize:10,fontWeight:700,padding:"3px 10px",borderRadius:20,background:st.bg,color:st.cor}}>{st.label}</span>
                    </div>
                  </div>
                  <div style={{display:"flex",gap:6,marginTop:10,paddingTop:10,borderTop:"1px solid #f1f5f9",flexWrap:"wrap"}}>
                    {(u.status==="convite_pendente"||u.status==="ativo")&&u.tokenConvite&&(
                      <>
                        <button onClick={()=>copiarLink(u)} style={{padding:"5px 11px",background:copiadoConvite?"#ecfdf5":"#f1f5f9",border:"none",borderRadius:6,fontFamily:"inherit",fontSize:10.5,fontWeight:600,cursor:"pointer",color:copiadoConvite?"#065f46":"#64748b"}}>{copiadoConvite?"✓ Link copiado":"📋 Copiar link de convite"}</button>
                        <button onClick={()=>abrirWhatsApp(u)} style={{padding:"5px 11px",background:"#ecfdf5",border:"none",borderRadius:6,fontFamily:"inherit",fontSize:10.5,fontWeight:600,cursor:"pointer",color:"#065f46"}}>💬 Enviar por WhatsApp</button>
                        {u.status==="convite_pendente"&&<button onClick={()=>reenviarConvite(u)} style={{padding:"5px 11px",background:"#fefce8",border:"none",borderRadius:6,fontFamily:"inherit",fontSize:10.5,fontWeight:600,cursor:"pointer",color:"#78350f"}}>↺ Reenviar convite</button>}
                      </>
                    )}
                    {u.status==="ativo"&&u.id!==usuarioAtual.id&&(
                      <button onClick={async()=>{
                        const t=gerarToken();
                        const updated=users.map(x=>x.id===u.id?{...x,tokenRedefinir:t,tokenRedefinirAt:new Date().toISOString()}:x);
                        await saveUsers(updated);setUsers(updated);
                        copiarTexto(`${window.location.origin}/convite/${t}`,u.id+"_redefinir");
                      }} style={{padding:"5px 11px",background:linkCopiado===u.id+"_redefinir"?"#ecfdf5":"#f1f5f9",border:"none",borderRadius:6,fontFamily:"inherit",fontSize:10.5,fontWeight:600,cursor:"pointer",color:linkCopiado===u.id+"_redefinir"?"#065f46":"#64748b"}}>{linkCopiado===u.id+"_redefinir"?"✓ Link copiado":"🔑 Gerar link de redefinição"}</button>
                    )}
                    {u.id!==usuarioAtual.id&&(
                      <>
                        {editandoPerfil!==u.id&&<button onClick={()=>setEditandoPerfil(u.id)} style={{padding:"5px 11px",background:"#eef2ff",border:"none",borderRadius:6,fontFamily:"inherit",fontSize:10.5,fontWeight:700,cursor:"pointer",color:C.b2}}>Mudar perfil</button>}
                        {u.status!=="ativo"&&u.status!=="convite_pendente"&&<button onClick={()=>alterarStatus(u.id,"ativo")} style={{padding:"5px 11px",background:"#ecfdf5",border:"none",borderRadius:6,fontFamily:"inherit",fontSize:10.5,fontWeight:700,cursor:"pointer",color:"#065f46"}}>Ativar</button>}
                        {u.status==="ativo"&&<button onClick={()=>alterarStatus(u.id,"inativo")} style={{padding:"5px 11px",background:"#f1f5f9",border:"none",borderRadius:6,fontFamily:"inherit",fontSize:10.5,fontWeight:700,cursor:"pointer",color:"#64748b"}}>Desativar</button>}
                        {u.status!=="bloqueado"&&<button onClick={()=>alterarStatus(u.id,"bloqueado")} style={{padding:"5px 11px",background:"#fef2f2",border:"none",borderRadius:6,fontFamily:"inherit",fontSize:10.5,fontWeight:700,cursor:"pointer",color:"#991b1b"}}>Bloquear</button>}
                        {u.status==="bloqueado"&&<button onClick={()=>alterarStatus(u.id,"inativo")} style={{padding:"5px 11px",background:"#fef2f2",border:"none",borderRadius:6,fontFamily:"inherit",fontSize:10.5,fontWeight:700,cursor:"pointer",color:"#991b1b"}}>Desbloquear</button>}
                      </>
                    )}
                  </div>
                </div>
              );
            })}
          </div>
        </div>
      </div>
    </div>
  );
}

