  async function enviarFotosPendentes(id,lista){
    const prontas=[];
    for(const foto of lista){
      if(foto.path){prontas.push(foto);continue;}
      const r=await fetch("/api/fotos/upload",{method:"POST",headers:{"Content-Type":"application/json"},credentials:"same-origin",body:JSON.stringify({captId:id,dataUrl:foto.refinadaUrl||foto.dataUrl})});
      const j=await r.json().catch(()=>({}));
      if(!r.ok) throw new Error(j.error||"Falha ao enviar foto.");
      prontas.push({...foto,path:j.path});
    }
    return prontas;
  }

  async function salvar(){
    const id=captId||Date.now().toString(36);

    let fotosEnviadas=fotos;
    if(fotos.some(ft=>!ft.path)){
      try{
        fotosEnviadas=await enviarFotosPendentes(id,fotos);
      }catch(e){
        toast("⚠️ Não foi possível enviar as fotos agora. Tente de novo em instantes.");
        return;
      }
      setFotos(fotosEnviadas);
    }

    const record={
      f,cat,subcatCasa,
      autorStatus:autorStatus||"aguardando",
      autorTs:autorTs?.toISOString()||null,
      authCode,
      validStatus,validObs,docsVerificados,precoAlinhado,
      fotos:fotosEnviadas.map(({dataUrl,refinadaUrl,originalUrl,...resto})=>({...resto,refinada:!!refinadaUrl})),descComercial,descAprovada,tituloAnuncio,galeriaConfirmada,latStatus,
      historico,
      results,comparaveis,diagComercial,estrategiaSelecionada,argumentoTexto,precCode,
      precoFinal,precoFinalStatus,acoesComerciais,
      ts:new Date().toISOString(),
    };

    // Trava de segurança: o storage tem limite de 5MB por registro.
    // Verificamos ANTES de tentar salvar para nunca falhar silenciosamente.
    const tamanhoBytes=new Blob([JSON.stringify(record)]).size;
    const LIMITE_SEGURO=4.0*1024*1024; // margem sob o limite de 4,5MB do servidor
    if(tamanhoBytes>LIMITE_SEGURO){
      const mb=(tamanhoBytes/1024/1024).toFixed(1);
      toast(`⚠️ Não foi possível salvar: o registro está em ${mb}MB, acima do limite seguro de 4MB. Remova algumas fotos (principalmente as maiores) e tente novamente.`);
      return;
    }

    setCaptId(id);
    setSaved(true);setSavedAt(new Date());setIsEditing(false);
    if(!autorStatus) setAutorStatus("aguardando");

    try{
      await window.storage.set("cap:"+id,JSON.stringify(record),true);
      setCaptacoes(prev=>{
        const filtered=prev.filter(c=>c.id!==id);
        return [{id,...record},...filtered];
      });
      toast("Rascunho salvo automaticamente.");
      // Gerar descrição automaticamente na primeira vez
      if(!descComercial){
        setTimeout(()=>gerarDescricaoComercial(),400);
      }
    }catch(e){
      console.error("Save:",e);
      toast("⚠️ Erro ao salvar. Tente novamente ou remova algumas fotos.");
    }
  }

