// Identifica um imóvel de forma estável, para reaproveitar a precificação
// quando é o MESMO imóvel, e gerar uma nova sempre que for um imóvel diferente.
// Só considera "mesmo imóvel" quando há um identificador específico o bastante
// (não basta bairro, que é compartilhado por vários imóveis diferentes).
function chaveImovelUnidade(f){
  if(!f) return "";
  const empreendimento=(f.empreendimento||"").trim().toLowerCase();
  const bairro=(f.bairro||"").trim().toLowerCase();
  const endereco=(f.endereco||"").trim().toLowerCase();
  const numero=(f.numero||"").trim().toLowerCase();
  const torre=(f.torre||"").trim().toLowerCase();
  const unidade=(f.unidade||"").trim().toLowerCase();
  const quadra=(f.quadra||"").trim().toLowerCase();
  const lote=(f.lote||"").trim().toLowerCase();

  // Apartamento/casa em condomínio: precisa do empreendimento + unidade (ou torre+unidade)
  if(empreendimento&&unidade) return ["emp",empreendimento,torre,unidade].join("|");
  // Casa de rua: precisa de endereço + número
  if(endereco&&numero) return ["end",bairro,endereco,numero].join("|");
  // Terreno (urbano ou em condomínio): precisa de quadra + lote
  if(quadra&&lote) return ["terreno",empreendimento,bairro,quadra,lote].join("|");
  // Sem identificador específico o bastante — nunca reaproveita, sempre precifica de novo
  return "";
}

